parameters.jsCode:
const respuesta = $input.first().json.message?.content;

// Comprobar que Gemma ha respondido
if (!respuesta) {
  throw new Error("Gemma no devolvió una respuesta");
}

// Convertir el texto JSON en un objeto JavaScript
let analisis;

try {
  analisis = JSON.parse(respuesta);
} catch (error) {
  analisis = {
    estado: "REVISION_MANUAL",
    desenfoque: "DESCONOCIDO",
    motivo: "No se pudo interpretar la respuesta de Gemma"
  };
}

// Comprobar los valores recibidos
const estados = ["APTA", "NO_APTA", "REVISION_MANUAL"];
const niveles = ["BAJO", "MEDIO", "ALTO"];

let estado = estados.includes(analisis.estado)
  ? analisis.estado
  : "REVISION_MANUAL";

const desenfoque = niveles.includes(analisis.desenfoque)
  ? analisis.desenfoque
  : "DESCONOCIDO";

// Evitar aprobar resultados contradictorios
if (estado === "APTA" && desenfoque !== "BAJO") {
  estado = "REVISION_MANUAL";
}

// Devolver el resultado organizado
return [{
  json: {
    estado: estado,
    desenfoque: desenfoque,
    motivo: typeof analisis.motivo === "string"
      ? analisis.motivo
      : "Se necesita revisar la imagen"
  }
}];

const item = $input.first(); //Obtiene primer elemento enviado deel form

// Accede a la imagen recibida
const imagen = item.binary?.Imagen;

// Comprobar que existe
if (!imagen) {
  throw new Error("No se ha recibido ninguna imagen");
}

// Comprobar el formato
if (!["image/jpeg", "image/png"].includes(imagen.mimeType)) {
  throw new Error("Formato de imagen no permitido");
}

// Devolver los datos sin perder la imagen
return [{
  json: {
    archivo: imagen.fileName,
    formato: imagen.mimeType,
    resultado: "Imagen recibida correctamente"
  },
  binary: item.binary
}];

const item = $input.first();


// Obtener los bytes de la imagen  // Recomendada DOc oficial n8n para acceder.
const buffer = await this.helpers.getBinaryDataBuffer(
  0,
  'Imagen'
);

// Comprobar tamaño máximo: 8 MiB
if (buffer.length > 8 * 1024 * 1024) {
  throw new Error("La imagen supera los 8 MiB");
}

// Convertir la imagen a Base64
const imagenBase64 = buffer.toString('base64');

// Preparar la salida
return [{
  json: {
    ...item.json,
    tamanoBytes: buffer.length,
    imagenBase64: imagenBase64
  },
  binary: item.binary
}];

